INSERT INTO "engines" VALUES(1,'valkey','Valkey','Redis-compatible data-structure server. Strings and counters, EXPIRE, lists, sorted sets, sets, streams, Lua for atomic composition. Reference material usually says Redis; the primitives are the same.','2026-09-12T19:58:22Z','2026-09-12T20:14:18Z');
INSERT INTO "engines" VALUES(2,'sqlite','SQLite','Embedded transactional SQL. Tables, UNIQUE and PRIMARY KEY, B-tree indexes, transactions, WAL mode, triggers. Expiry and queue semantics come from schema plus application logic, not dedicated primitives. Best fit when the component lives inside one application or host.','2026-09-12T19:58:22Z','2026-09-12T20:14:18Z');
INSERT INTO "engines" VALUES(3,'postgres','PostgreSQL','Server-side MVCC SQL. Row locks, FOR UPDATE SKIP LOCKED, advisory locks, LISTEN/NOTIFY, INSERT ... ON CONFLICT, rich index types, sequences, materialized views. Many patterns that need application convention in SQLite get a dedicated concurrency primitive here.','2026-09-12T19:58:22Z','2026-09-12T20:14:18Z');
INSERT INTO "patterns" VALUES(1,'counter','Counter','counting','','2026-09-12T19:58:22Z','2026-09-12T20:14:18Z','A single number that many callers bump at the same time, like a page-view total or items in stock. The hard part is making sure two updates that land at once are both counted instead of one overwriting the other. The store does the addition itself so callers never read, add, and write back.','Page views, likes, inventory levels, quota consumption, and metrics where many processes bump the same value. In a distributed system the read-modify-write race is the classic lost-update bug, and an atomic increment removes it. It is also the building block under fixed-window rate limiting.','[{"title":"Redis INCR command reference (with counter and rate-limiter patterns)","url":"https://redis.io/docs/latest/commands/incr/"},{"title":"Valkey INCR command reference","url":"https://valkey.io/commands/incr/"},{"title":"PostgreSQL UPDATE statement reference","url":"https://www.postgresql.org/docs/current/sql-update.html"}]','["No increment is lost under concurrent writers."]');
INSERT INTO "patterns" VALUES(2,'ttl-cache','TTL cache','caching','','2026-09-12T19:58:22Z','2026-09-12T20:14:18Z','A place to keep a copy of something expensive to compute or fetch, so the next request can reuse it. Each entry carries an expiry time, and once that passes the entry is treated as gone. Serving stale data is the main risk, so the expiry is the whole point.','Caching query results, rendered pages, API responses, and computed aggregates to cut latency and load on the source of truth. Bounds staleness by time when invalidating on every write is impractical. Also absorbs thundering-herd traffic on hot keys.','[{"title":"Redis EXPIRE command reference (how Redis expires keys)","url":"https://redis.io/docs/latest/commands/expire/"},{"title":"Redis key eviction policies (maxmemory, LRU, LFU, volatile-ttl)","url":"https://redis.io/docs/latest/develop/reference/eviction/"},{"title":"Time to live - Wikipedia","url":"https://en.wikipedia.org/wiki/Time_to_live"}]','["An entry is never read after its expiry."]');
INSERT INTO "patterns" VALUES(3,'session-store','Session store','caching','','2026-09-12T19:58:22Z','2026-09-12T20:14:18Z','Keeps a logged-in user''s state between requests, looked up by the session id in their cookie. Each session has one owner and expires after a period of inactivity or a fixed lifetime. It is a cache with a strict rule that one id means one session.','Web login sessions, shopping carts, and per-user temporary state that must be reachable from any app server behind a load balancer. Keeps app servers stateless so they can be scaled or replaced freely. Expiry enforces logout on idle and bounds storage.','[{"title":"Server Session State - Martin Fowler (PoEAA)","url":"https://martinfowler.com/eaaCatalog/serverSessionState.html"},{"title":"Database Session State - Martin Fowler (PoEAA)","url":"https://martinfowler.com/eaaCatalog/databaseSessionState.html"},{"title":"OWASP Session Management Cheat Sheet","url":"https://cheatsheetseries.owasp.org/cheatsheets/Session_Management_Cheat_Sheet.html"}]','["One session id maps to one live session.","A session expires on time."]');
INSERT INTO "patterns" VALUES(4,'idempotency-key','Idempotency key','idempotency','','2026-09-12T19:58:22Z','2026-09-12T20:14:18Z','Lets a client safely retry a request without causing the effect twice, such as charging a card again. The client sends a unique key with the request, and the server remembers the key and the answer it gave. A retry with the same key gets the saved answer instead of doing the work again.','Payment and order APIs where a client retry after a timeout must not double-charge or double-create. Any at-least-once delivery path (queues, webhooks, retries) needs the receiver to dedupe by key. Turns an unreliable network into exactly-once effects.','[{"title":"Stripe API: Idempotent requests","url":"https://docs.stripe.com/api/idempotent_requests"},{"title":"Designing robust and predictable APIs with idempotency - Stripe Engineering","url":"https://stripe.com/blog/idempotency"},{"title":"Making retries safe with idempotent APIs - Amazon Builders'' Library","url":"https://aws.amazon.com/builders-library/making-retries-safe-with-idempotent-APIs/"}]','["A repeated request with the same key produces one effect.","A repeated request with the same key gets the same answer."]');
INSERT INTO "patterns" VALUES(5,'fifo-queue','FIFO work queue','queueing','','2026-09-12T19:58:22Z','2026-09-12T20:14:18Z','A line of jobs that workers take from the front, roughly in the order they were added. Each job should be handed to one worker only, even when many workers grab at once. The tricky part is claiming a job without two workers both believing they got it.','Background jobs like sending email, resizing images, and calling third-party APIs, anything slow or failure-prone that should not run in the request path. Decouples producers from consumers and smooths bursts. The claim step is where double-processing and lost jobs happen.','[{"title":"Redis lists (LPUSH/BRPOP, queues and blocking operations)","url":"https://redis.io/docs/latest/develop/data-types/lists/"},{"title":"PostgreSQL SELECT: The Locking Clause (FOR UPDATE ... SKIP LOCKED)","url":"https://www.postgresql.org/docs/current/sql-select.html"},{"title":"Reliable Queue Pattern (LMOVE to a processing list) - Redis Patterns","url":"https://redis.antirez.com/fundamental/reliable-queue.html"}]','["Every enqueued job is handed to exactly one worker at a time.","Jobs are handed out roughly in enqueue order.","No enqueued job is lost."]');
INSERT INTO "patterns" VALUES(6,'priority-queue','Priority queue','queueing','','2026-09-12T19:58:22Z','2026-09-12T20:14:18Z','A queue where each job has an importance level, and workers always take the most important job that is ready. Arrival order only matters among jobs of equal priority. Low-priority jobs can wait a long time if important work keeps arriving.','Mixed workloads where urgent work (password resets, paying customers) must not wait behind bulk work (nightly reports). Also scheduling in build systems and task runners. Watch for starvation of low-priority jobs under constant high-priority load.','[{"title":"Redis sorted sets","url":"https://redis.io/docs/latest/develop/data-types/sorted-sets/"},{"title":"BZPOPMIN - blocking pop of the lowest-score member","url":"https://redis.io/docs/latest/commands/bzpopmin/"},{"title":"Priority queue - Wikipedia","url":"https://en.wikipedia.org/wiki/Priority_queue"}]','["A ready higher-priority job is claimed before a lower-priority one.","Each job is claimed by one worker at a time."]');
INSERT INTO "patterns" VALUES(7,'delayed-queue','Delayed queue / scheduler','queueing','','2026-09-12T19:58:22Z','2026-09-12T20:14:18Z','A queue where each job has a time it is allowed to run, like sending a reminder an hour from now. Workers only pick up jobs whose time has arrived. Nothing runs early, and every due job eventually gets picked up.','Reminders, scheduled publishing, trial expirations, retries after backoff, and cancel-if-not-confirmed timers. Replaces cron plus a table scan with a per-job due time. Must survive restarts without losing or re-running jobs.','[{"title":"Delayed Queue Pattern (sorted set scored by run-at timestamp) - Redis Patterns","url":"https://redis.antirez.com/fundamental/delayed-queue.html"},{"title":"Redis job queue use case (FIFO, priority, delayed execution)","url":"https://redis.io/docs/latest/develop/use-cases/job-queue/"},{"title":"Amazon SQS delay queues","url":"https://docs.aws.amazon.com/AWSSimpleQueueService/latest/SQSDeveloperGuide/sqs-delay-queues.html"}]','["No job runs before its due time.","Every due job eventually runs."]');
INSERT INTO "patterns" VALUES(8,'retry-queue','Retry queue','queueing','','2026-09-12T19:58:22Z','2026-09-12T20:14:18Z','When a job fails, it goes back in line to try again after a waiting period that usually grows with each failure. The job records how many times it has been tried and when it may run next. After too many failures it stops being retried.','Calls to flaky external services, transient database deadlocks, and network errors where a second try usually succeeds. Exponential backoff with jitter protects a struggling downstream from retry storms. Attempt limits stop poison messages from looping forever.','[{"title":"Exponential Backoff And Jitter - AWS Architecture Blog","url":"https://aws.amazon.com/blogs/architecture/exponential-backoff-and-jitter/"},{"title":"Google SRE Book, Ch. 22: Addressing Cascading Failures (Retries)","url":"https://sre.google/sre-book/addressing-cascading-failures/"},{"title":"Jitter: Making Things Better With Randomness - Marc Brooker","url":"https://brooker.co.za/blog/2015/03/21/backoff.html"}]','["A failed job is retried only after its backoff has elapsed.","A job is retried no more than its attempt limit."]');
INSERT INTO "patterns" VALUES(9,'dead-letter-queue','Dead-letter queue','queueing','','2026-09-12T19:58:22Z','2026-09-12T20:14:18Z','A holding area for jobs that failed too many times and were pulled out of the live queue. They are kept rather than thrown away so someone can inspect, fix, or replay them. It keeps broken jobs from clogging the workers.','Capturing jobs with bad input, missing records, or bugs so they stop consuming worker time yet remain available for debugging and replay after a fix. Standard in every message-broker deployment. Growth of the dead-letter queue is an early failure signal worth alerting on.','[{"title":"Dead Letter Channel - Enterprise Integration Patterns","url":"https://www.enterpriseintegrationpatterns.com/patterns/messaging/DeadLetterChannel.html"},{"title":"Using dead-letter queues in Amazon SQS","url":"https://docs.aws.amazon.com/AWSSimpleQueueService/latest/SQSDeveloperGuide/sqs-dead-letter-queues.html"},{"title":"Dead letter queue - Wikipedia","url":"https://en.wikipedia.org/wiki/Dead_letter_queue"}]','["A job that exhausts its retries leaves the live queue.","A dead-lettered job is not lost."]');
INSERT INTO "patterns" VALUES(10,'consumer-groups','Consumer groups','queueing','','2026-09-12T19:58:22Z','2026-09-12T20:14:18Z','A way for a team of workers to share one stream of messages so that each message is handled by exactly one of them. The group tracks which messages are in progress and how far it has read. If a worker crashes, its unfinished messages can be handed to another.','Scaling out event processing so many workers share one stream without duplicate handling, as in Kafka-style consumers. Checkpointing lets a restarted worker resume where it left off. Pending-entry tracking handles worker crashes by reassigning their messages.','[{"title":"Redis Streams (consumer groups, XREADGROUP, XPENDING, XCLAIM)","url":"https://redis.io/docs/latest/develop/data-types/streams/"},{"title":"Streams Consumer Group Patterns (recovery, XAUTOCLAIM, poison pills) - Redis Patterns","url":"https://redis.antirez.com/fundamental/streams-consumer-patterns.html"},{"title":"Kafka Consumer for Confluent Platform (consumer groups)","url":"https://docs.confluent.io/platform/current/clients/consumer.html"}]','["Each message is processed by one member of the group.","Progress survives a crash of any member."]');
INSERT INTO "patterns" VALUES(11,'outbox','Outbox pattern','queueing','','2026-09-12T19:58:22Z','2026-09-12T20:14:18Z','Solves the problem of saving a change and telling another system about it, without one happening and the other not. The outgoing message is written to an outbox table in the same transaction as the business change. A separate process then reads the outbox and delivers the messages.','Publishing domain events to a message bus after a database write without the dual-write problem, where the write commits but the publish fails or the reverse. Core of reliable microservice integration and event-driven architectures. Also used for transactional email and webhook delivery.','[{"title":"Pattern: Transactional outbox - microservices.io","url":"https://microservices.io/patterns/data/transactional-outbox.html"},{"title":"Transactional outbox pattern - AWS Prescriptive Guidance","url":"https://docs.aws.amazon.com/prescriptive-guidance/latest/cloud-design-patterns/transactional-outbox.html"},{"title":"Guaranteed Delivery - Enterprise Integration Patterns","url":"https://www.enterpriseintegrationpatterns.com/patterns/messaging/GuaranteedMessaging.html"}]','["A business write and its outgoing message commit together, or neither does.","Every committed outbox message is eventually delivered."]');
INSERT INTO "patterns" VALUES(12,'lease','Lease','coordination','','2026-09-12T19:58:22Z','2026-09-12T20:14:18Z','Temporary ownership of a resource that must be renewed to keep. If the owner crashes or stops renewing, the lease runs out and someone else can take over. That timeout is what keeps a dead owner from blocking everyone forever.','Electing one active worker for a cron-like job across many replicas, holding a shard or partition, or marking a task as in progress. Handles the owner dying by expiring, which a plain lock cannot. Renewal keeps a healthy owner in place.','[{"title":"Lease - Patterns of Distributed Systems (martinfowler.com)","url":"https://martinfowler.com/articles/patterns-of-distributed-systems/lease.html"},{"title":"Leader election in distributed systems - Amazon Builders'' Library (Marc Brooker, PDF)","url":"https://d1.awsstatic.com/builderslibrary/pdfs/leader-election-in-distributed-systems.pdf"},{"title":"Lease (computer science) - Wikipedia","url":"https://en.wikipedia.org/wiki/Lease_(computer_science)"}]','["At most one owner holds the resource at a time.","Ownership lapses if the owner dies."]');
INSERT INTO "patterns" VALUES(13,'lock','Lock','coordination','','2026-09-12T19:58:22Z','2026-09-12T20:14:18Z','Guarantees only one process is inside a piece of work at a time. The holder takes the lock, does the work, and releases it, and nobody else may release it on their behalf. An expiry protects against a holder that dies while holding it.','Preventing two processes from running the same migration, deploy step, or per-account update at once. Guards critical sections in application code across machines. Fencing tokens protect against a paused holder acting after its lock has expired.','[{"title":"Distributed Locks with Redis (SET NX PX, Redlock) - Redis Docs","url":"https://redis.io/docs/latest/develop/clients/patterns/distributed-locks/"},{"title":"How to do distributed locking - Martin Kleppmann","url":"https://martin.kleppmann.com/2016/02/08/how-to-do-distributed-locking.html"},{"title":"Explicit Locking, incl. Advisory Locks - PostgreSQL Docs","url":"https://www.postgresql.org/docs/current/explicit-locking.html"}]','["Only the holder is inside the critical section.","Only the holder can release the lock."]');
INSERT INTO "patterns" VALUES(14,'semaphore','Semaphore / bounded concurrency','coordination','','2026-09-12T19:58:22Z','2026-09-12T20:14:18Z','Like a lock, but allows up to N holders at once instead of one, such as capping concurrent calls to a slow API. Each holder takes a slot and gives it back when done. If a holder crashes, its slot must eventually be freed.','Capping concurrent calls to a rate-limited third-party API, limiting parallel expensive reports, or bounding connections to a fragile legacy system. A backpressure tool for when a downstream cannot absorb unbounded parallelism.','[{"title":"Understanding Redis race conditions and locks (counting semaphores with ZSETs) - Redis","url":"https://redis.io/glossary/redis-race-condition/"},{"title":"Controlling concurrency in distributed systems using AWS Step Functions (distributed semaphore) - AWS Compute Blog","url":"https://aws.amazon.com/blogs/compute/controlling-concurrency-in-distributed-systems-using-aws-step-functions/"},{"title":"Semaphore (programming) - Wikipedia","url":"https://en.wikipedia.org/wiki/Semaphore_(programming)"}]','["No more than N holders run at once.","A crashed holder''s slot returns."]');
INSERT INTO "patterns" VALUES(15,'task-ownership','Task ownership / worker coordination','coordination','','2026-09-12T19:58:22Z','2026-09-12T20:14:18Z','Tracks which worker is responsible for each task that is currently running. Every in-flight task has exactly one live owner, and a task whose owner disappears can be reassigned. It is a queue combined with leases.','Worker pools where each in-flight task must be attributable to a live worker so orphaned work can be detected and reassigned. Underlies job runners, workflow engines, and crawler fleets. Heartbeats plus lease expiry are how dead workers are found.','[{"title":"HeartBeat - Patterns of Distributed Systems (martinfowler.com)","url":"https://martinfowler.com/articles/patterns-of-distributed-systems/heartbeat.html"},{"title":"SELECT ... FOR UPDATE SKIP LOCKED (The Locking Clause) - PostgreSQL Docs","url":"https://www.postgresql.org/docs/current/sql-select.html"},{"title":"You Don''t Need a Job Queue, Postgres Already Has SKIP LOCKED - Prisma Blog","url":"https://www.prisma.io/blog/you-dont-need-a-job-queue-postgres-already-has-skip-locked"}]','["Every in-flight task has exactly one live owner.","A task whose owner dies is reassigned."]');
INSERT INTO "patterns" VALUES(16,'distributed-coordination','Distributed / local coordination','coordination','','2026-09-12T19:58:22Z','2026-09-12T20:14:18Z','The general problem of several processes agreeing on shared state without overwriting each other''s work. Locks, leases, queues, and notifications are all tools for it. The right tool depends on whether the processes live on one machine or many.','Leader election, configuration changes every node must see, rendezvous between services, and any only-one-of-us-should-do-this situation. The first design decision is whether a local transactional store is enough or a networked service is needed.','[{"title":"Managing Critical State: Distributed Consensus for Reliability - Google SRE Book","url":"https://sre.google/sre-book/managing-critical-state/"},{"title":"NOTIFY (LISTEN/NOTIFY) - PostgreSQL Docs","url":"https://www.postgresql.org/docs/current/sql-notify.html"},{"title":"Advisory Lock Functions - PostgreSQL Docs","url":"https://www.postgresql.org/docs/current/functions-admin.html"}]','["Participants agree on shared state without stepping on each other."]');
INSERT INTO "patterns" VALUES(17,'fixed-window-rate-limiter','Fixed-window rate limiter','rate-limiting','','2026-09-12T19:58:22Z','2026-09-12T20:14:18Z','Allows at most N requests per key in each fixed time slice, such as 100 per minute starting on the minute. A counter per key and window is bumped on each request and starts over when the window rolls. It is simple but allows a burst of 2N across a window boundary.','API quotas like 1000 requests per hour per key, login-attempt limits, and abuse throttling where a cheap counter is enough. Fits when a burst across a window boundary is acceptable. Usually the first limiter a service ships.','[{"title":"INCR - Pattern: rate limiter (INCR + EXPIRE) - Redis Docs","url":"https://redis.io/docs/latest/commands/incr/"},{"title":"INCR - Pattern: rate limiter - Valkey Docs","url":"https://valkey.io/commands/incr/"},{"title":"Rate Limiting (Redis best practices with INCR/EXPIRE) - Redis Glossary","url":"https://redis.io/glossary/rate-limiting/"}]','["At most N requests are admitted per key per window."]');
INSERT INTO "patterns" VALUES(18,'sliding-window-rate-limiter','Sliding-window rate limiter','rate-limiting','','2026-09-12T19:58:22Z','2026-09-12T20:14:18Z','Allows at most N requests per key in any trailing period, such as the last 60 seconds from right now. It avoids the burst at a boundary that fixed windows allow by looking at recent request times instead of a single counter. It costs more to track.','Fairer API throttling where a client must not double its allowance by straddling a window edge. Protects backends with tight capacity and enforces per-tenant fairness in gateways. Costs more memory per key than a fixed window.','[{"title":"How we built rate limiting capable of scaling to millions of domains - Cloudflare Blog","url":"https://blog.cloudflare.com/counting-things-a-lot-of-different-things/"},{"title":"Build 5 Rate Limiters with Redis: Fixed Window, Sliding Window, Token Bucket, and Leaky Bucket - Redis Tutorials","url":"https://redis.io/tutorials/howtos/ratelimiting/"},{"title":"Rate limiting - Wikipedia","url":"https://en.wikipedia.org/wiki/Rate_limiting"}]','["At most N requests are admitted per key in any trailing window."]');
INSERT INTO "patterns" VALUES(19,'token-bucket','Token bucket','rate-limiting','','2026-09-12T19:58:22Z','2026-09-12T20:14:18Z','A bucket holds tokens that refill at a steady rate up to a maximum. Each request spends one token, and a request is refused when the bucket is empty. This allows short bursts up to the bucket size while keeping the long-run rate steady.','Shaping traffic that is naturally bursty, such as user actions or batch uploads, while holding a steady average rate. The standard model in network quality-of-service and most cloud API limits. Lets clients briefly spend saved-up capacity.','[{"title":"Token bucket - Wikipedia","url":"https://en.wikipedia.org/wiki/Token_bucket"},{"title":"Scaling your API with rate limiters - Stripe Engineering","url":"https://stripe.com/blog/rate-limiters"},{"title":"Build 5 Rate Limiters with Redis (Token bucket section) - Redis Tutorials","url":"https://redis.io/tutorials/howtos/ratelimiting/"}]','["Tokens refill at a fixed rate.","Tokens never exceed the burst size.","Each token is spent at most once."]');
INSERT INTO "patterns" VALUES(20,'leaderboard','Leaderboard','ranking','','2026-09-12T19:58:22Z','2026-09-12T20:14:18Z','A ranked list of members by score, like top players or most active users. Scores change often, and reads should show a consistent ranking rather than a half-updated one. The main need is fast lookup by rank and fast score updates.','Game rankings, top sellers, trending content, and most-active-user lists that update constantly and are read far more than written. Needs rank lookup and the neighbours around a member. Sorted structures make both cheap.','[{"title":"Redis sorted sets","url":"https://redis.io/docs/latest/develop/data-types/sorted-sets/"},{"title":"Valkey sorted sets","url":"https://valkey.io/topics/sorted-sets/"},{"title":"PostgreSQL Tutorial: Window Functions","url":"https://www.postgresql.org/docs/current/tutorial-window.html"}]','["Reads see a consistent ranking of current scores."]');
INSERT INTO "patterns" VALUES(21,'dedup','Set membership / dedup','idempotency','','2026-09-12T19:58:22Z','2026-09-12T20:14:18Z','Remembers which items have already been seen so each one is acted on at most once. Adding an item that is already present does nothing rather than failing. It is the simplest form of idempotency.','Ignoring duplicate webhook deliveries, duplicate events from at-least-once brokers, and repeated form submissions. Also tracking which items a batch job has already processed. Set membership is the cheapest route to exactly-once handling.','[{"title":"Redis SADD command reference","url":"https://redis.io/docs/latest/commands/sadd/"},{"title":"PostgreSQL INSERT ... ON CONFLICT (upsert / DO NOTHING)","url":"https://www.postgresql.org/docs/current/sql-insert.html#SQL-ON-CONFLICT"},{"title":"Pattern: Idempotent Consumer - microservices.io","url":"https://microservices.io/patterns/communication-style/idempotent-consumer.html"}]','["A member is counted or acted on at most once."]');
INSERT INTO "patterns" VALUES(22,'expiring-uniqueness','Expiring uniqueness / reservation','idempotency','','2026-09-12T19:58:22Z','2026-09-12T20:14:18Z','Reserves a name or slot for one holder for a limited time, like holding a username during signup or a seat during checkout. If the holder does not finish, the reservation expires and the name becomes available again.','Username holds during signup, seat and inventory reservations during checkout, and short-lived claims on external identifiers. Solves the abandoned-flow problem where a held name would otherwise never be released.','[{"title":"Redis SET command reference (NX / EX options and lock pattern)","url":"https://redis.io/docs/latest/commands/set/"},{"title":"PostgreSQL Constraints: Exclusion Constraints","url":"https://www.postgresql.org/docs/current/ddl-constraints.html#DDL-CONSTRAINTS-EXCLUSION"},{"title":"Distributed Locks with Redis (single-instance SET NX PX and Redlock)","url":"https://redis.io/docs/latest/develop/clients/patterns/distributed-locks/"}]','["One holder reserves a name at a time.","A reservation lapses on its own."]');
INSERT INTO "patterns" VALUES(23,'secondary-index','Secondary index','indexing','','2026-09-12T19:58:22Z','2026-09-12T20:14:18Z','An extra lookup structure that finds rows by something other than their primary key, such as users by email. The index must always agree with the data it points to. Databases maintain this for you; a key-value store makes the application do it.','Looking up users by email, orders by customer, or sessions by user id when the primary key is something else. In a key-value store the application must maintain it on every write. Index drift is a common source of subtle bugs.','[{"title":"PostgreSQL: CREATE INDEX","url":"https://www.postgresql.org/docs/current/sql-createindex.html"},{"title":"SQLite: Query Planning","url":"https://www.sqlite.org/queryplanner.html"},{"title":"Redis: Secondary indexing","url":"https://redis.io/docs/latest/develop/clients/patterns/indexes/"}]','["The index agrees with the base data it points at."]');
INSERT INTO "patterns" VALUES(24,'time-ordered-data','Time-ordered data','indexing','','2026-09-12T19:58:22Z','2026-09-12T20:14:18Z','Data that is mostly read by time range, such as events between two timestamps. Storage is arranged so those range reads return every matching row in order without scanning everything.','Event logs, audit trails, metrics, and activity feeds queried as everything between two times. Also cursor pagination over recent activity. Storage ordered by time keeps range reads cheap as the table grows.','[{"title":"PostgreSQL: BRIN Indexes","url":"https://www.postgresql.org/docs/current/brin.html"},{"title":"Redis sorted sets","url":"https://redis.io/docs/latest/develop/data-types/sorted-sets/"}]','["Range reads by time return every matching row in order."]');
INSERT INTO "patterns" VALUES(25,'pubsub','Pub/Sub','messaging','','2026-09-12T19:58:22Z','2026-09-12T20:14:18Z','Lets one process broadcast a message and every currently listening process receive it. Messages are not stored, so a subscriber that is not connected at that moment simply misses them. Good for wake-up signals, not for anything that must not be lost.','Cache invalidation across app servers, pushing live updates to websocket connections, and waking workers when new work arrives instead of polling. Best for ephemeral signals where a missed message is harmless.','[{"title":"Redis Pub/sub","url":"https://redis.io/docs/latest/develop/pubsub/"},{"title":"PostgreSQL: NOTIFY","url":"https://www.postgresql.org/docs/current/sql-notify.html"},{"title":"PostgreSQL: LISTEN","url":"https://www.postgresql.org/docs/current/sql-listen.html"}]','["A live subscriber sees messages published while it is connected."]');
INSERT INTO "patterns" VALUES(26,'durable-event-log','Durable event log','log','','2026-09-12T19:58:22Z','2026-09-12T20:14:18Z','An append-only record of everything that happened, in order, that survives crashes. Entries are never edited or deleted, only added. Other systems can replay the log from any point to rebuild their state.','Audit trails, event sourcing, change data capture, and replayable inter-service integration where consumers rebuild state from history. The foundation of stream processing. Retention and compaction are the long-term concerns.','[{"title":"The Log: What every software engineer should know about real-time data''s unifying abstraction (Jay Kreps)","url":"https://www.linkedin.com/blog/engineering/distributed-systems/log-what-every-software-engineer-should-know-about-real-time-datas-unifying"},{"title":"Redis Streams","url":"https://redis.io/docs/latest/develop/data-types/streams/"},{"title":"Event Sourcing (Martin Fowler)","url":"https://martinfowler.com/eaaDev/EventSourcing.html"}]','["Appends are totally ordered.","Appended entries are never rewritten.","Appended entries survive a crash."]');
INSERT INTO "patterns" VALUES(27,'state-machine','State machine','state','','2026-09-12T19:58:22Z','2026-09-12T20:14:18Z','A record that moves through a fixed set of states, like an order going from placed to paid to shipped, with only certain transitions allowed. Each transition checks the current state before changing it. Two concurrent changes must not both succeed.','Order lifecycles, payment flows, document approval, and job status where an invalid or duplicate transition, like shipping twice or paying a cancelled order, is a real bug. Concurrent updates must act on the same observed state. Makes illegal states unrepresentable.','[{"title":"Finite-state machine (Wikipedia)","url":"https://en.wikipedia.org/wiki/Finite-state_machine"},{"title":"Optimistic Offline Lock (Martin Fowler, PoEAA)","url":"https://martinfowler.com/eaaCatalog/optimisticOfflineLock.html"},{"title":"Optimistic concurrency control (Wikipedia)","url":"https://en.wikipedia.org/wiki/Optimistic_concurrency_control"}]','["Only legal transitions happen.","Transitions happen one at a time, from the state actually observed."]');
INSERT INTO "patterns" VALUES(28,'materialized-view','Materialized view / derived state','state','','2026-09-12T19:58:22Z','2026-09-12T20:14:18Z','A precomputed answer to an expensive query, stored so reads are cheap. It is derived from source data and refreshed either on every change or on a schedule. The trade-off is how stale the derived copy is allowed to be.','Dashboards, per-user counts, denormalized read models, and search projections too expensive to compute on every read. Central to CQRS-style read models. The refresh strategy sets the staleness bound.','[{"title":"PostgreSQL: CREATE MATERIALIZED VIEW","url":"https://www.postgresql.org/docs/current/sql-creatematerializedview.html"},{"title":"CQRS (Martin Fowler)","url":"https://martinfowler.com/bliki/CQRS.html"},{"title":"Materialized View pattern (Azure Architecture Center)","url":"https://learn.microsoft.com/en-us/azure/architecture/patterns/materialized-view"}]','["Derived state matches the source data as of a known point."]');
